import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.oeh4wjV1.js";const h=JSON.parse('{"title":"Booster-Draft Cube","description":"","frontmatter":{},"headers":[],"relativePath":"formats/cube/variants/booster-draft.md","filePath":"formats/cube/variants/booster-draft.md","lastUpdated":1792425987000}'),s={name:"formats/cube/variants/booster-draft.md"};function n(i,e,d,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="booster-draft-cube" tabindex="-1">Booster-Draft Cube <a class="header-anchor" href="#booster-draft-cube" aria-label="Permalink to &quot;Booster-Draft Cube&quot;">​</a></h1><p><a href="./../">Cube parent page</a> · <strong>Rules: ordinary booster drafting with a reusable card pool</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>Prepare a curated cube, an adequate supply of basic lands, and tokens or counters for its cards. Eight players is a common draft size; the pool needs at least <strong>45 cards per player</strong> for the three-pack, fifteen-card setup below.</p><p>A cube&#39;s theme, rarity restrictions, power level, and choice to use duplicates are construction decisions. They do not change the draft procedure unless the owner explicitly adds a rule.</p><h2 id="prepare-the-draft" tabindex="-1">Prepare the draft <a class="header-anchor" href="#prepare-the-draft" aria-label="Permalink to &quot;Prepare the draft&quot;">​</a></h2><ol><li>Choose the cube list and any announced special rules.</li><li>Randomize its cards and make <strong>three fifteen-card packs for each player</strong>.</li><li>Keep unused cube cards outside the draft.</li><li>Seat players in a circle and give each player their three packs.</li><li>Everyone opens only the first pack.</li></ol><p>The owner may use deliberately seeded packs, but must specify that construction method. It is not part of the randomized default.</p><h2 id="draft-pack-one" tabindex="-1">Draft pack one <a class="header-anchor" href="#draft-pack-one" aria-label="Permalink to &quot;Draft pack one&quot;">​</a></h2><ol><li>Look privately at the cards in the current pack.</li><li>Choose <strong>one card</strong> and place it face down in your drafted pool.</li><li>Pass the remaining cards to the player on your <strong>left</strong>.</li><li>Receive the next pack from your right and repeat.</li><li>Continue until every card from the first round of packs has been selected.</li></ol><p>Keep selections separate from packs being passed so cards cannot be accidentally returned to a pack.</p><h2 id="draft-packs-two-and-three" tabindex="-1">Draft packs two and three <a class="header-anchor" href="#draft-packs-two-and-three" aria-label="Permalink to &quot;Draft packs two and three&quot;">​</a></h2><p>Open pack two when everyone has finished the first round. Repeat the same one-card-per-pick procedure, but pass to the <strong>right</strong>.</p><p>For pack three, pass to the <strong>left</strong> again.</p><p>Each player finishes with <strong>45 drafted cards</strong>. A procedure that takes two cards at a time, drafts commanders separately, or passes in a different pattern is a separate variant and must be announced.</p><h2 id="build-decks" tabindex="-1">Build decks <a class="header-anchor" href="#build-decks" aria-label="Permalink to &quot;Build decks&quot;">​</a></h2><ul><li>Build a deck of <strong>at least 40 cards</strong> from your drafted pool.</li><li>Add ordinary basic lands from the land supply as needed.</li><li>You may play any number of copies of a card you actually drafted; the constructed four-copy limit does not apply.</li><li>Your undrafted remainder is not available. Your drafted cards that are not in the main deck form your sideboard.</li><li>You may change the deck using that sideboard and the supplied basic lands between games, keeping at least 40 cards.</li></ul><p>Drafting a legendary creature does not automatically turn this into Commander. This ruleset does not create a command zone, color-identity restriction, commander tax, or commander-damage condition.</p><h2 id="play-games" tabindex="-1">Play games <a class="header-anchor" href="#play-games" aria-label="Permalink to &quot;Play games&quot;">​</a></h2><p>Choose pairings and a match structure before play. In normal two-player games, each player starts at <strong>20 life</strong>, draws <strong>seven cards</strong>, and uses normal mulligans. Determine who chooses to play or draw normally; the player taking the first turn skips their first draw step.</p><p>Play ordinary Magic turns and combat with normal victory and loss conditions. If the group wants multiplayer free-for-all matches instead, announce that structure and use its normal multiplayer setup.</p><h2 id="reset-the-cube" tabindex="-1">Reset the cube <a class="header-anchor" href="#reset-the-cube" aria-label="Permalink to &quot;Reset the cube&quot;">​</a></h2><p>At the end of play, return every drafted card to the cube, separate the borrowed basic lands, and check that tokens and other components have been collected. The cube is reusable; drafting does not transfer ownership of its cards.</p><h2 id="other-cube-structures" tabindex="-1">Other cube structures <a class="header-anchor" href="#other-cube-structures" aria-label="Permalink to &quot;Other cube structures&quot;">​</a></h2><p>Powered, unpowered, peasant, pauper, set, and theme cubes can all use this procedure. Commander Cube, Winston draft, grid draft, sealed pools, and rotisserie draft require their own additional procedures; mentioning those possibilities is not a complete ruleset for them.</p><p>Sources: <a href="https://magic.wizards.com/en/formats/booster-draft" target="_blank" rel="noreferrer">Wizards&#39; Booster Draft rules</a>, <a href="https://magic.wizards.com/en/news/feature/building-your-first-cube-2016-05-19" target="_blank" rel="noreferrer">Building Your First Cube</a>, and <a href="https://magic.wizards.com/en/news/making-magic/power-cubed-2012-11-27" target="_blank" rel="noreferrer">Power, Cubed</a>.</p>',26)])])}const f=a(s,[["render",n]]);export{h as __pageData,f as default};
